SRC = {
    'cpsc_dryer': [{"name":"U.S. Consumer Product Safety Commission — Clothes Dryer Safety","url":"https://www.cpsc.gov/s3fs-public/5022.pdf","note":"Dryer fire prevention, lint removal, venting, and safe operation."}],
    'food': [{"name":"FoodSafety.gov — Cold Food Storage Chart","url":"https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts","note":"Refrigerated storage times and safe cold-storage guidance."}],
    'epa_water': [{"name":"U.S. Environmental Protection Agency — Secondary Drinking Water Standards","url":"https://www.epa.gov/sdwa/secondary-drinking-water-standards-guidance-nuisance-chemicals","note":"Taste, odor, color, iron, copper, and other aesthetic drinking-water issues."}],
    'epa_lead': [{"name":"U.S. Environmental Protection Agency — Basic Information about Lead in Drinking Water","url":"https://www.epa.gov/ground-water-and-drinking-water/basic-information-about-lead-drinking-water","note":"Lead in drinking water, testing, and why taste is not a reliable safety test."}],
    'watersense': [{"name":"U.S. Environmental Protection Agency WaterSense — Fix a Leak Week","url":"https://www.epa.gov/watersense/fix-leak-week","note":"Household leak detection and repair, including dripping faucets."}],
    'aci': [{"name":"American Cleaning Institute — Cleaning Tips","url":"https://www.cleaninginstitute.org/cleaning-tips","note":"Household cleaning, product-label use, and surface-safe cleaning practices."}],
    'nwfa': [{"name":"National Wood Flooring Association — Wood Floor Maintenance","url":"https://woodfloors.org/maintenance/","note":"Routine wood-floor cleaning, moisture control, and finish protection."}],
    'sleep_pillow': [{"name":"Sleep Foundation — How Often Should You Replace Your Pillows?","url":"https://www.sleepfoundation.org/best-pillows/how-often-should-you-replace-your-pillows","note":"Replacement considerations based on support, hygiene, and pillow material."}],
    'sleep_rotate': [{"name":"Sleep Foundation — How Often Should You Rotate or Flip Your Mattress?","url":"https://www.sleepfoundation.org/mattress-information/how-often-should-you-rotate-or-flip-your-mattress","note":"Mattress rotation and why many modern mattresses should not be flipped."}],
    'samsung_screen': [{"name":"Samsung Support — How to clean your TV screen","url":"https://www.samsung.com/us/support/answer/ANS00046181/","note":"Screen-safe cleaning, microfiber cloths, and avoiding direct liquid application."}],
    'cpsc_co': [{"name":"U.S. Consumer Product Safety Commission — Carbon Monoxide Information Center","url":"https://www.cpsc.gov/Safety-Education/Safety-Education-Centers/Carbon-Monoxide-Information-Center","note":"Carbon-monoxide risks from fuel-burning appliances and ventilation."}],
}

def source_note_es(items):
    repl = {
        'Dryer fire prevention, lint removal, venting, and safe operation.':'Prevención de incendios en secadoras, retirada de pelusa, ventilación y uso seguro.',
        'Refrigerated storage times and safe cold-storage guidance.':'Tiempos de conservación refrigerada y pautas de almacenamiento seguro.',
        'Taste, odor, color, iron, copper, and other aesthetic drinking-water issues.':'Sabor, olor, color, hierro, cobre y otros problemas organolépticos del agua potable.',
        'Lead in drinking water, testing, and why taste is not a reliable safety test.':'Plomo en agua potable, análisis y por qué el sabor no sirve para determinar seguridad.',
        'Household leak detection and repair, including dripping faucets.':'Detección y reparación de fugas domésticas, incluidos grifos que gotean.',
        'Household cleaning, product-label use, and surface-safe cleaning practices.':'Limpieza doméstica, uso según etiqueta y prácticas compatibles con cada superficie.',
        'Routine wood-floor cleaning, moisture control, and finish protection.':'Limpieza habitual de suelos de madera, control de humedad y protección del acabado.',
        'Replacement considerations based on support, hygiene, and pillow material.':'Criterios de sustitución según soporte, higiene y material de la almohada.',
        'Mattress rotation and why many modern mattresses should not be flipped.':'Rotación del colchón y razones por las que muchos modelos modernos no deben voltearse.',
        'Screen-safe cleaning, microfiber cloths, and avoiding direct liquid application.':'Limpieza segura de pantallas, uso de microfibra y evitar aplicar líquido directamente.',
        'Carbon-monoxide risks from fuel-burning appliances and ventilation.':'Riesgos de monóxido de carbono en aparatos de combustión y necesidad de ventilación.'
    }
    out=[]
    for s in items:
        x=dict(s); x['note']=repl.get(x['note'],x['note']); out.append(x)
    return out

def write_one(n,tg,lang,title,slug,meta,intent,excerpt,family,subcats,types,primary,body,faq,sources,image):
    is_es = lang == 'es'
    data = {
        'schema_version':1,
        'id':f"{lang}-{n:03d}-{slug}",
        'article_number':n,
        'translation_group':tg,
        'language':lang,
        'locale':'es-ES' if is_es else 'en-US',
        'market_context':'Español internacional; guía doméstica práctica, segura y comprensible para hogares de España y Latinoamérica.' if is_es else 'United States and Canada; practical, safety-first household guidance written natively for North American readers.',
        'title':title,
        'slug':slug,
        'seo':{'title':title if len(title) <= 62 else title[:59].rstrip()+ '…','meta_description':meta,'search_intent':intent},
        'excerpt':excerpt,
        'taxonomy':{'food_family':family,'food_subcategories':subcats,'article_types':types,'primary_article_type':primary},
        'content_html':body.strip(),
        'faq':faq,
        'sources':source_note_es(sources) if is_es else sources,
        'image':{'concept':image,'alt':title.replace('¿','').replace('?','')},
        'status':'publish'
    }
    p = ROOT / lang / f"{n:03d}-{slug}.json"
    p.write_text(json.dumps(data, ensure_ascii=False, separators=(',',':'))+'\n', encoding='utf-8')

def pair(n,tg,common,es,en):
    for lang,d in [('es',es),('en',en)]:
        write_one(n,tg,lang,d['title'],d['slug'],d['meta'],d['intent'],d['excerpt'],common['family'],common['subcats'],common['types'],common['primary'],d['body'],d['faq'],sum((SRC[k] for k in common['sources']),[]),d['image'])

# 151
pair(151,'151-dryer-wont-start',{'family':'laundry-appliances','subcats':['dryer','power'],'types':['troubleshooting','safety'],'primary':'troubleshooting','sources':['cpsc_dryer']},
{'title':'¿Por qué no enciende la secadora?','slug':'por-que-no-enciende-secadora','meta':'Si la secadora no enciende, revisa alimentación, puerta, controles y señales de sobrecalentamiento antes de asumir una avería interna.','intent':'Diagnosticar una secadora que no arranca, separando problemas de alimentación y controles de fallos que requieren servicio técnico.','excerpt':'Una secadora que no hace nada puede tener un problema tan simple como falta de alimentación o un bloqueo de controles, pero también puede haberse detenido por una avería interna. Empieza por lo que puedes comprobar sin desmontarla.','body':'''<p>Si pulsas Inicio y la secadora no responde, <strong>primero distingue entre “no tiene corriente” y “tiene corriente pero no arranca”</strong>. Esa observación evita cambiar piezas a ciegas.</p><h2>Comprueba si el panel tiene vida</h2><p>Si no hay luces ni pantalla, revisa el enchufe y el cuadro eléctrico. Las secadoras eléctricas de gran potencia pueden usar más de un polo del interruptor automático; si ha saltado, restablécelo una sola vez. Si vuelve a dispararse, no insistas.</p><h2>Si el panel enciende, revisa puerta y controles</h2><p>La puerta debe cerrar y accionar su interruptor de seguridad. Retira ropa atrapada en el cierre y escucha si el pestillo hace clic. Comprueba también si está activo el bloqueo infantil, un inicio diferido o una combinación especial de botones.</p><h2>Algunos modelos exigen mantener pulsado Inicio</h2><p>No todas arrancan con un toque breve. Consulta el panel o el manual y mantén el botón el tiempo indicado. Si oyes un zumbido pero el tambor no empieza a moverse, el problema ya no parece un simple ajuste.</p><h2>No puentes interruptores ni abras la carcasa</h2><p>El interruptor de puerta, fusibles térmicos, motor y cableado pueden impedir el arranque. Son comprobaciones internas que implican electricidad y, en secadoras de gas, además combustible. No anules dispositivos de seguridad para “probar”.</p><h2>Cuándo dejarla fuera de servicio</h2><p>Desconecta la secadora y pide revisión si huele a quemado, hay marcas en el enchufe, el interruptor automático salta de nuevo, se oyen chasquidos eléctricos o el cable está dañado. Si simplemente no arranca pero la alimentación y los controles parecen normales, lleva al técnico esa información: acelera el diagnóstico.</p><p>La secuencia útil es corta: <strong>alimentación, puerta, bloqueo/ajustes y respuesta del motor</strong>. A partir de ahí, la reparación deja de ser una comprobación doméstica básica.</p>''','faq':[{'question':'¿Debo restablecer el automático varias veces?','answer':'No. Hazlo una vez. Si vuelve a saltar, deja de usar la secadora y busca la causa.'},{'question':'¿Puede ser solo la puerta?','answer':'Sí. Si el cierre no acciona su interruptor de seguridad, muchos modelos no arrancan.'},{'question':'¿Conviene abrirla para mirar el fusible térmico?','answer':'No como primer paso. Las pruebas internas requieren desconectar y acceder a componentes eléctricos; si las comprobaciones externas no resuelven el problema, pide servicio.'}],'image':'Secadora doméstica con panel encendido y puerta abierta mientras una persona revisa el cierre, fotografía editorial realista, sin texto ni marcas.'},
{'title':'Why Won’t My Dryer Start?','slug':'why-dryer-wont-start','meta':'If your dryer will not start, check power, the door, control settings, and signs of electrical trouble before assuming an internal part failed.','intent':'Diagnose a dryer that will not start by separating power and control issues from internal faults that need service.','excerpt':'A dryer that does nothing may have a simple power or control problem, or it may have stopped because an internal safety device or component failed. Start with checks that do not require opening the cabinet.','body':'''<p>If you press Start and nothing happens, <strong>first separate “no power” from “has power but will not run.”</strong> That one observation narrows the problem quickly.</p><h2>See whether the control panel is alive</h2><p>If the display and lights are dead, check the plug and electrical panel. Full-size electric dryers often use a high-voltage double-pole circuit. Reset a tripped breaker once; if it trips again, stop rather than repeatedly resetting it.</p><h2>If the panel works, check the door and controls</h2><p>The door must close far enough to operate its safety switch. Remove clothing caught in the opening and make sure the latch engages. Also look for Control Lock, Child Lock, Delay Start, or another setting that can prevent an immediate start.</p><h2>Some dryers require a deliberate Start press</h2><p>On certain models you must hold Start for a second or two rather than tap it. Follow the panel or manual. If the dryer hums but the drum does not begin moving, you have moved beyond a simple setting issue.</p><h2>Do not bypass a safety switch</h2><p>A door switch, thermal fuse, motor, belt switch, or control can prevent operation. Diagnosing those parts requires cabinet access and electrical testing; gas dryers add fuel-system hazards. Do not defeat an interlock just to see whether the machine will run.</p><h2>Stop using it when the symptoms are electrical</h2><p>Unplug the dryer and arrange service if you smell burning insulation, see heat damage at the receptacle, hear electrical arcing, find a damaged cord, or the breaker trips again. If the controls look normal but the machine simply will not start, tell the technician exactly what the panel does and whether you hear a click or hum.</p><p>A useful order is <strong>power, door, controls, then motor response</strong>. Once those external checks are exhausted, internal diagnosis is the next level.</p>''','faq':[{'question':'Should I keep resetting the breaker?','answer':'No. Reset it once. If it trips again, leave the dryer off and have the circuit or appliance checked.'},{'question':'Can a bad door latch stop the dryer?','answer':'Yes. The dryer may refuse to run if the door does not operate its safety switch.'},{'question':'Should I open the dryer to test the thermal fuse?','answer':'Not as a basic homeowner check. Internal testing involves electrical components and should be done only with appropriate service procedures.'}],'image':'Household dryer with an illuminated control panel and open door while someone checks the latch, realistic editorial photography, no branding.'})

# 152
pair(152,'152-dryer-drum-not-turning',{'family':'laundry-appliances','subcats':['dryer','drum'],'types':['troubleshooting','safety'],'primary':'troubleshooting','sources':['cpsc_dryer']},
{'title':'¿Por qué el tambor de la secadora no gira?','slug':'por-que-tambor-secadora-no-gira','meta':'Si la secadora enciende pero el tambor no gira, distingue entre sobrecarga, objeto atascado, correa o motor antes de intentar una reparación.','intent':'Diagnosticar por qué el tambor de una secadora no gira y saber qué comprobaciones externas son seguras antes de solicitar reparación.','excerpt':'Si la secadora parece arrancar pero el tambor no se mueve, fíjate en el sonido: silencio, zumbido y giro manual libre apuntan a causas diferentes.','body':'''<p>Cuando la secadora enciende pero el tambor se queda quieto, el sonido importa. <strong>Un motor que zumba, un clic seguido de silencio o un tambor que gira a mano con demasiada facilidad no cuentan la misma historia.</strong></p><h2>Descarta primero una carga demasiado pesada</h2><p>Apaga la máquina, saca parte de la ropa y vuelve a probar una carga pequeña. Edredones mojados, alfombras o prendas muy pesadas pueden exigir más par del que el equipo puede mover con normalidad.</p><h2>Con la secadora apagada, busca una obstrucción evidente</h2><p>Una prenda, cordón o pequeño objeto puede quedar atrapado en el borde del tambor. No metas herramientas ni manos en zonas que no sean accesibles desde la puerta.</p><h2>La sensación al girar el tambor es una pista, no una prueba definitiva</h2><p>Con el aparato desconectado, algunos tambores ofrecen una resistencia suave. Si de repente gira muchísimo más libre que antes, una correa rota es posible. Si está muy duro, podría haber un rodillo, polea u objeto bloqueando el movimiento.</p><h2>Un zumbido sin giro puede señalar motor o atasco</h2><p>No mantengas el motor zumbando durante varios intentos: puede calentarse. Si una carga ligera no cambia nada, deja de probar.</p><h2>La reparación suele exigir abrir el aparato</h2><p>Correa, polea tensora, rodillos y motor están dentro del gabinete. Si hay olor a quemado, chispas, calentamiento anormal o el interruptor automático salta, desconecta inmediatamente. Una secadora que calienta sin girar tampoco debe dejarse funcionando: la ropa puede sobrecalentarse.</p><p>Antes de llamar, anota si el motor se oye, si el tambor ofrece resistencia al girarlo desconectado y si el problema apareció de golpe. Esas tres pistas suelen orientar mucho el diagnóstico.</p>''','faq':[{'question':'¿Puedo usar la secadora si calienta pero no gira?','answer':'No. La ropa no se mueve ni distribuye el calor correctamente y puede sobrecalentarse.'},{'question':'¿Un tambor muy suelto significa correa rota?','answer':'Es una posibilidad frecuente, pero no es una prueba definitiva; la confirmación requiere acceso interno.'},{'question':'¿Debo seguir probando si el motor zumba?','answer':'No durante repetidos intentos. Un motor bloqueado puede calentarse.'}],'image':'Interior de una secadora doméstica con el tambor detenido y una carga pequeña, fotografía editorial realista, sin texto.'},
{'title':'Why Is My Dryer Drum Not Turning?','slug':'why-dryer-drum-not-turning','meta':'If the dryer powers on but the drum will not turn, separate overload, obstruction, belt, and motor clues before attempting a repair.','intent':'Diagnose a dryer drum that will not turn and know which external checks are safe before service.','excerpt':'If the dryer appears to start but the drum stays still, listen closely. Silence, humming, and an unusually free-spinning drum point in different directions.','body':'''<p>When the dryer powers up but the drum stays still, the sound matters. <strong>A hum, a click followed by silence, and a drum that suddenly turns very freely by hand suggest different failure paths.</strong></p><h2>Rule out an overloaded drum</h2><p>Turn the dryer off, remove part of the load, and try a small load. Wet comforters, rugs, and other heavy items can require much more starting torque than ordinary clothing.</p><h2>Look for an obvious obstruction with power off</h2><p>A garment, drawstring, or small object can wedge near the drum edge. Inspect only areas reachable from the door; do not probe behind panels.</p><h2>Hand rotation is a clue, not a diagnosis</h2><p>With the dryer unplugged, many drums have some smooth resistance. If yours suddenly feels much easier to turn than it used to, a broken drive belt is possible. If it is unusually hard to move, a roller, idler, or trapped object may be binding.</p><h2>A humming motor should not be repeatedly stalled</h2><p>If a light load does not change the symptom, stop cycling Start over and over. A stalled motor can overheat.</p><h2>Most drive repairs require cabinet access</h2><p>The belt, idler pulley, rollers, and motor are internal parts. Disconnect the dryer if you smell hot insulation, see sparks, or the breaker trips. Do not let a dryer continue heating while the drum is stationary because the load cannot tumble and distribute heat normally.</p><p>Before scheduling service, note whether you can hear the motor, how the unplugged drum feels when turned, and whether the failure happened suddenly. Those observations are more useful than simply reporting “it does not spin.”</p>''','faq':[{'question':'Can I run the dryer if it heats but does not tumble?','answer':'No. A stationary load can overheat because it is not moving through the airflow normally.'},{'question':'Does a very loose-feeling drum prove the belt broke?','answer':'No, but it is a useful clue. Internal inspection is needed to confirm the drive failure.'},{'question':'Should I keep pressing Start if the motor hums?','answer':'No. Repeatedly stalling a motor can overheat it.'}],'image':'Open household dryer with a stationary drum and a small load inside, realistic editorial photography, no text or branding.'})

